import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const l="/assets/collection-root.CzqozG4O.jpg",g=JSON.parse('{"title":"📂 合集解析结果不完整","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/collection-download-error.md","filePath":"troubleshooting/collection-download-error.md","lastUpdated":1794555324000}'),i={name:"troubleshooting/collection-download-error.md"};function n(s,o,c,d,p,h){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="📂-合集解析结果不完整" tabindex="-1">📂 合集解析结果不完整 <a class="header-anchor" href="#📂-合集解析结果不完整" aria-label="Permalink to &quot;📂 合集解析结果不完整&quot;">​</a></h1><h2 id="🔍-解析与选择下载内容" tabindex="-1">🔍 解析与选择下载内容 <a class="header-anchor" href="#🔍-解析与选择下载内容" aria-label="Permalink to &quot;🔍 解析与选择下载内容&quot;">​</a></h2><p>粘贴合集成员的 BV / AV 播放地址后，应用会检测所属合集并解析全部成员。</p><ul><li><strong>多 P 投稿</strong>：每个 BV 显示为独立的可展开分组，展开后可查看和勾选其中的分 P；分组复选框用于选择整个投稿。</li><li><strong>单 P 投稿</strong>：显示为普通条目。</li><li><strong>开始下载</strong>：勾选需要的条目后，点击「下载所选」。解析本身不会启动下载。</li></ul><p>例如，<code>https://www.bilibili.com/video/BV17zDWYwEj8/?p=2</code> 属于「测试」合集。验证时，共解析出 <strong>2 个 BV、3 个条目</strong>：一个包含 2 个分 P 的投稿分组，以及另一个单 P 投稿。链接中的 <code>p=2</code> 不会将解析结果限制为单个分 P。合集内容可能随后续编辑发生变化。</p><p>合集入口地址也可以直接解析指定合集。没有所属合集信息的普通投稿直接解析当前 BV；视频标题里写着「合集」不代表它属于 B 站的合集。</p><h2 id="💡-结果不完整时" tabindex="-1">💡 结果不完整时 <a class="header-anchor" href="#💡-结果不完整时" aria-label="Permalink to &quot;💡 结果不完整时&quot;">​</a></h2><ol><li><strong>确认应用和内核已更新。</strong> 此功能需要应用中的合集检测及多 P 分组功能，以及 uiya-yutto 0.3.5 或更新内核。源码 / uv 环境需同步依赖，自定义 Python 环境也需要升级内核。</li><li><strong>更新后完全退出并重新打开应用。</strong> 已启动的 yutto server 会继续使用原先加载的内核。</li><li><strong>查看控制台。</strong> 合集检测失败时，应用会提示并继续解析当前视频；成员失效、访问权限和网络错误也可能导致部分条目失败。</li></ol><h2 id="✅-使用合集入口排查" tabindex="-1">✅ 使用合集入口排查 <a class="header-anchor" href="#✅-使用合集入口排查" aria-label="Permalink to &quot;✅ 使用合集入口排查&quot;">​</a></h2><p>点击播放页的合集名称，在 UP 主空间打开合集，再复制合集入口地址解析。</p><p><img src="'+l+'" alt="collection-root"></p><p>合集入口通常形如 <code>https://space.bilibili.com/&lt;UP主ID&gt;/lists/&lt;合集ID&gt;?type=season</code>。这种地址明确指定合集，不依赖当前视频详情中的合集信息。</p><p>如果合集入口可以完整解析，而成员播放页没有列出全部成员，请反馈两个地址、应用 / 内核版本和控制台错误。</p>',13)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
